ywords": ["string", ...], "Negate": true|false }, "SentimentConfiguration": { "RuleName": "string", "SentimentType": "NEGATIVE", "TimePeriod": integer }, "IssueDetectionConfiguration": { "RuleName": "string" } } ... ] }
